// Build 2 items: one per fixing session, both for TODAY (Europe/Warsaw)
const now = new Date();
// Use Warsaw local time components via toLocaleString trick
const warsaw = new Date(now.toLocaleString('en-US', { timeZone: 'Europe/Warsaw' }));
const yyyy = warsaw.getFullYear();
const mm = String(warsaw.getMonth() + 1).padStart(2, '0');
const dd = String(warsaw.getDate()).padStart(2, '0');
const dateIso = `${yyyy}-${mm}-${dd}`;
const dateParam = `${yyyy}${mm}${dd}`;

return [1, 2].map((session) => ({
  json: {
    fixing_date: dateIso,
    fixing_session: session,
    date_param: dateParam,
    month_param: String(warsaw.getMonth() + 1),
    year_param: String(yyyy),
    source_url: `https://www.bondspot.pl/fixing_obligacji?date=${dateParam}&month=${warsaw.getMonth() + 1}&year=${yyyy}&type=${session}`
  }
}));

// Parse the BondSpot fixing table from raw HTML.
// Each input item already carries fixing_date / fixing_session / source_url.
// We emit ONE output item per input item, containing the parsed rows[] array
// plus a status field ('ok' | 'empty').

const out = [];
for (const item of $input.all()) {
  const meta = item.json;
  const html = (item.json && item.json.data) || (item.json && item.json.body) || item.json.raw || '';
  // n8n HTTP node with responseFormat=text stores body in `data` field
  const source = typeof html === 'string' ? html : String(html);

  const parseNum = (s) => {
    if (s === undefined || s === null) return null;
    let t = String(s).trim();
    if (t === '' || t === '-' || t === '\u2013' || t === '\u2014') return null;
    t = t.replace(/\s/g, '').replace(',', '.');
    const n = parseFloat(t);
    return Number.isFinite(n) ? n : null;
  };

  // Bond rows: LP (digit), name (free text), ISIN (PL + 10 chars), then 6 numeric cells.
  const rowRegex = /<tr>\s*<td>(\d+)<\/td>\s*<td>([^<]+)<\/td>\s*<td>(PL[A-Z0-9]{10})<\/td>\s*<td[^>]*>([^<]*)<\/td>\s*<td[^>]*>([^<]*)<\/td>\s*<td[^>]*>([^<]*)<\/td>\s*<td[^>]*>([^<]*)<\/td>\s*<td[^>]*>([^<]*)<\/td>\s*<td[^>]*>([^<]*)<\/td>\s*<\/tr>/g;

  const rows = [];
  let m;
  while ((m = rowRegex.exec(source)) !== null) {
    rows.push({
      fixing_date: meta.fixing_date,
      fixing_session: meta.fixing_session,
      isin: m[3].trim(),
      lp: parseInt(m[1], 10),
      name: m[2].trim(),
      bid_price: parseNum(m[4]),
      ask_price: parseNum(m[5]),
      bid_yield: parseNum(m[6]),
      ask_yield: parseNum(m[7]),
      fixing_price: parseNum(m[8]),
      fixing_yield: parseNum(m[9]),
      source_url: meta.source_url
    });
  }

  out.push({
    json: {
      fixing_date: meta.fixing_date,
      fixing_session: meta.fixing_session,
      source_url: meta.source_url,
      rows,
      rows_count: rows.length,
      status: rows.length > 0 ? 'ok' : 'empty'
    }
  });
}
return out;
